+    b.timer -= dt;
+    b.speed *= 0.85;
+    return;
+  }
+
+  const maxSpeed = p.blueSpeed * b.genes.speed;
+  let targetSpeed = 0;
+  steer.x = 0;
+  steer.y = 0;
+
+  if (b.action === "eat") {
+    const tree = w.trees[b.targetId];
+    const slot = tree.slots[b.targetSlot];
+    b.timer -= dt;
+    slot.eatProgress = 1 - Math.max(0, b.timer) / Math.max(1e-6, b.timerTotal);
