+  let fy = 0;
+  let threats = 0;
+  let cx = 0;
+  let cy = 0;
+
+  const q = w.grid.query(b.x, b.y, vis);
+  for (let k = 0; k < q.count; k++) {
+    const o = w.blobs[q.ids[k]];
+    if (o === b || o.action === "fade") continue;
+    const dx = b.x - o.x;
+    const dy = b.y - o.y;
+    const d2 = dx * dx + dy * dy;
+    if (o.species === "red") {
+      if (o.action === "pause" || d2 > vis2) continue;
+      const d = Math.sqrt(d2) + 1e-6;
+      const weight = 1 / (d + 0.4);
+      fx += (dx / d) * weight;
+      fy += (dy / d) * weight;
+      threats++;
