+        fy += ny * outward * 1.2;
+      }
+      const k = (r - edge) / 3;
+      fx += nx * k;
+      fy += ny * k;
+      len = Math.hypot(fx, fy) || 1;
+      fx /= len;
+      fy /= len;
+    }
