+  const q = w.grid.query(b.x, b.y, reach);
+  let sx = 0;
+  let sy = 0;
+  for (let k = 0; k < q.count; k++) {
+    const o = w.blobs[q.ids[k]];
+    if (o === b || o.species !== b.species || o.action === "fade") continue;
+    const dx = b.x - o.x;
+    const dy = b.y - o.y;
+    const d2 = dx * dx + dy * dy;
+    const lim = rb + radiusOf(o.species) + 0.35;
+    if (d2 >= lim * lim || d2 < 1e-8) continue;
+    const d = Math.sqrt(d2);
+    const k2 = (lim - d) / lim;
+    sx += (dx / d) * k2;
+    sy += (dy / d) * k2;
