  if (heavyRed) {
    const early = h.t.findIndex((x) => x > 240);
    const end = early < 0 ? h.t.length : early;
    let minI = 0;
    for (let i = 0; i < end; i++) if (h.blue[i] < h.blue[minI]) minI = i;
    const redFall = st.redGoneAt ?? (redNow < st.redMax * 0.4 ? t : null);
    if (h.blue[minI] < ip.blueStart * 0.7 && (redFall === null || h.t[minI] <= redFall)) {
      lines.push(
        `Red started strong: blue dipped first (down to ${h.blue[minI]} at ${fmtT(h.t[minI])})${redFall !== null ? `, then red faded later (${st.redGoneAt !== null ? `gone at ${fmtT(redFall)}` : `now ${redNow}`})` : ""}.`,
