import {
  clampParam,
  PARAM_META,
  presetParams,
  PRESETS,
  RESET_KEYS,
  RULES,
  type ParamKey,
  type Params,
} from "../sim/params";
import { createRng } from "../sim/rng";
import { summarize, type Summary } from "../sim/summary";
import type { SimEvent } from "../sim/types";
import { createWorld, step, type World } from "../sim/world";

export interface Snapshot {
  version: number;
  worldVersion: number;
  historyVersion: number;
  running: boolean;
  time: number;
  counts: World["counts"];
  params: Params;
  presetId: string | null;
  pendingReset: ParamKey[];
  selected: number | null;
  selectedTree: number | null;
  follow: boolean;
  turntable: boolean;
  lagging: boolean;
}

const MAX_STEPS_PER_FRAME = 60;
const MAX_QUEUED_EVENTS = 600;

export class SimController {
  world: World;
  params: Params;
  running = false;
  presetId: string | null = "balanced";
  worldVersion = 0;
  selected: number | null = null;
  selectedTree: number | null = null;
  follow = false;
  turntable = false;
  lagging = false;

  private acc = 0;
  private events: SimEvent[] = [];
  private listeners = new Set<() => void>();
  private version = 0;
  private snap: Snapshot;
  private lastNotify = 0;
  private summaryCache: { v: number; at: number; s: Summary } | null = null;
  private lagFrames = 0;

  constructor() {
