      transparent: true,
      opacity: 0.32,
      color: "#6e4a36",
      depthWrite: false,
    }),
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -DISH_DEPTH - 0.02;
  group.add(shadow);

  group.add(buildDecor(radius, seed, trees));
  return group;
}

