export interface Params {
  fruitGrowth: number;
  fruitLimit: number;
  fruitDelay: number;
  trees: number;
  worldSize: number;

  blueEnergyUse: number;
  blueSpeed: number;
  blueVision: number;
  blueCopy: number;
  blueEatTime: number;
  blueStart: number;

  redEnergyUse: number;
  redSpeed: number;
  redVision: number;
  redContact: number;
  redCopy: number;
  redPauseTime: number;
  redStart: number;

  traitDrift: number;
  seed: number;
  simSpeed: number;
}

export type ParamKey = keyof Params;
export type ParamGroup = "garden" | "blue" | "red" | "world";

export interface ParamMeta {
  key: ParamKey;
  label: string;
  group: ParamGroup;
  min: number;
  max: number;
  step: number;
  help: string;
  resetOnly?: boolean;
  log?: boolean;
  format: (v: number) => string;
}

/** Fixed rules of the garden that are not exposed as sliders. */
export const RULES = {
  dt: 1 / 20,
  fruitEnergy: 22,
  redEfficiency: 0.8,
  copyOverhead: 0.15,
  idleShare: 0.25,
  maxEnergyMult: 1.3,
  blueRadius: 0.4,
  redRadius: 0.46,
  treeTrunkRadius: 0.32,
  treeReach: 0.95,
  maxBlobs: 1400,
  maxFruitSlots: 10,
  fadeTime: 1.1,
  startledTime: 0.55,
  chaseStamina: 5,
  tiredTime: 1.6,
  redSpacing: 2.2,
  fleeBurst: 1.2,
  shelterRadius: 1.8,
  shelterSlots: 4,
  shelterSpotDistance: 1.8,
  shelterFreezeDistance: 2.4,
  sampleInterval: 0.5,
} as const;

export const DEFAULT_PARAMS: Params = {
  fruitGrowth: 0.1,
  fruitLimit: 5,
  fruitDelay: 6,
  trees: 16,
  worldSize: 16,

  blueEnergyUse: 2,
  blueSpeed: 2,
  blueVision: 4.5,
  blueCopy: 60,
  blueEatTime: 1.4,
  blueStart: 40,

  redEnergyUse: 2.6,
  redSpeed: 2.4,
  redVision: 6,
  redContact: 45,
  redCopy: 90,
  redPauseTime: 2.5,
  redStart: 8,

  traitDrift: 0.05,
  seed: 7,
  simSpeed: 2,
};

const fixed = (d: number, unit = "") => (v: number) => `${v.toFixed(d)}${unit}`;

export const PARAM_META: ParamMeta[] = [
  {
    key: "fruitGrowth",
    label: "Fruit growth speed",
    group: "garden",
    min: 0.02,
    max: 0.5,
    step: 0.01,
    log: true,
    help: "How fast a new fruit swells on the branch once it starts growing.",
    format: (v) => `${(1 / v).toFixed(v > 0.2 ? 1 : 0)}s to ripen`,
  },
  {
    key: "fruitLimit",
    label: "Fruit limit",
    group: "garden",
    min: 1,
    max: 10,
    step: 1,
    help: "Most fruit a single tree can hold at once.",
    format: (v) => `${v} per tree`,
  },
  {
    key: "fruitDelay",
    label: "Fruit return delay",
    group: "garden",
    min: 0,
    max: 30,
    step: 0.5,
