          if (slot.claimedBy >= 0) {
            const p = slot.eatProgress;
            if (mouthOf(slot.claimedBy, this.mouth)) {
              const travel = easeOutCubic(smooth(0, 0.32, p));
              v2.lerp(this.mouth, travel);
