      const c = oc.lengthSq() - l.r * l.r;
      const disc = b * b - c;
      if (disc < 0) continue;
      const tFar = -b + Math.sqrt(disc);
      if (tFar > far) {
        far = tFar;
        hitLump = l;
      }
    }
    const p = center.clone().addScaledVector(dir, far);
    const n = p.clone().sub(hitLump.pos).normalize();
    slots.push(p.addScaledVector(n, FRUIT_R * 0.45));
    slotNormals.push(n);
