    this.canopy.count = n * LUMPS;
    this.fruits.count = n * SLOTS;
    this.leaves.count = n * SLOTS;
    this.shake = new Float32Array(n);
    this.pop = new Float32Array(n * SLOTS);
    this.prevGrowth = new Float32Array(n * SLOTS).fill(-1);

