        let ripeness = 1;
        v2.copy(l.slots[si]).applyMatrix4(tm);

        const prev = this.prevGrowth[idx];
        if (prev >= 0 && prev < 1 && slot.growth >= 1 && slot.claimedBy < 0) this.pop[idx] = 1;
        this.prevGrowth[idx] = slot.growth;
        this.pop[idx] *= Math.exp(-dt * 4);

