          lm.compose(v2, q.identity(), s.set(scale, scale * 1.06, scale));
          this.fruits.setMatrixAt(idx, lm);
          this.fruits.setColorAt(idx, c.copy(UNRIPE).lerp(RIPE, ripeness * ripeness));
