+        eyeWide = 1.3;
+        mouthKind = "oh";
+        break;
+      }
+      case "flee":
+        eyeWide = 1.2;
+        mouthKind = "oh";
+        mouthOpen = 0.8;
+        pitch += 0.08;
+        break;
+      case "chase":
+        eyeWide = 1.08;
+        pitch += 0.07;
+        break;
+      case "lurk":
+        sy *= 0.95;
