export interface Params {
  fruitGrowth: number;
  fruitLimit: number;
  fruitDelay: number;
  trees: number;
  worldSize: number;

  blueEnergyUse: number;
  blueSpeed: number;
  blueVision: number;
  blueCopy: number;
  blueEatTime: number;
  blueStart: number;

  redEnergyUse: number;
  redSpeed: number;
  redVision: number;
  redContact: number;
  redCopy: number;
  redPauseTime: number;
  redStart: number;

  traitDrift: number;
  seed: number;
  simSpeed: number;
}

export type ParamKey = keyof Params;
export type ParamGroup = "garden" | "blue" | "red" | "world";

export interface ParamMeta {
  key: ParamKey;
  label: string;
  group: ParamGroup;
  min: number;
  max: number;
  step: number;
  help: string;
  resetOnly?: boolean;
  log?: boolean;
  format: (v: number) => string;
}

/** Fixed rules of the garden that are not exposed as sliders. */
export const RULES = {
  dt: 1 / 20,
  fruitEnergy: 22,
  redEfficiency: 0.8,
  copyOverhead: 0.15,
  idleShare: 0.25,
  maxEnergyMult: 1.3,
  blueRadius: 0.4,
  redRadius: 0.46,
  treeTrunkRadius: 0.32,
  treeReach: 0.95,
  maxBlobs: 1400,
  maxFruitSlots: 10,
  fadeTime: 1.1,
  startledTime: 0.55,
  chaseStamina: 5,
  tiredTime: 1.6,
  redSpacing: 2.2,
  fleeBurst: 1.2,
  shelterRadius: 1.8,
  shelterSlots: 4,
  shelterSpotDistance: 0,
  hideMemory: 4,
  shelterFreezeDistance: 2.4,
  fearNear: 1,
  boldBelow: 0.2,
  redNestRadius: 0,
  redNestMax: 2,
  boldFleeDistance: 1.8,
  huntTime: [3, 6] as const,
  lurkTime: [2, 5] as const,
  sampleInterval: 0.5,
} as const;

export const DEFAULT_PARAMS: Params = {
  fruitGrowth: 0.1,
  fruitLimit: 5,
  fruitDelay: 6,
  trees: 20,
  worldSize: 18,

  blueEnergyUse: 2,
  blueSpeed: 2,
  blueVision: 4.5,
  blueCopy: 60,
  blueEatTime: 1.4,
  blueStart: 60,

  redEnergyUse: 1.5,
  redSpeed: 2.2,
  redVision: 3.5,
  redContact: 45,
  redCopy: 150,
  redPauseTime: 2.5,
  redStart: 8,

  traitDrift: 0.05,
  seed: 7,
  simSpeed: 4,
};

const fixed = (d: number, unit = "") => (v: number) => `${v.toFixed(d)}${unit}`;

export const PARAM_META: ParamMeta[] = [
  {
    key: "fruitGrowth",
    label: "Fruit growth speed",
    group: "garden",
    min: 0.02,
    max: 0.5,
    step: 0.01,
    log: true,
    help: "How fast a new fruit swells on the branch once it starts growing.",
    format: (v) => `${(1 / v).toFixed(v > 0.2 ? 1 : 0)}s to ripen`,
  },
  {
    key: "fruitLimit",
    label: "Fruit limit",
    group: "garden",
    min: 1,
    max: 10,
    step: 1,
    help: "Most fruit a single tree can hold at once.",
    format: (v) => `${v} per tree`,
  },
  {
    key: "fruitDelay",
    label: "Fruit return delay",
    group: "garden",
    min: 0,
    max: 30,
    step: 0.5,
    help: "Rest time on the branch after a fruit is eaten, before a new one begins to grow.",
    format: fixed(1, "s"),
  },
  {
    key: "trees",
    label: "Starting fruit trees",
    group: "garden",
    min: 1,
    max: 40,
    step: 1,
    resetOnly: true,
    help: "Number of fruit trees planted when the garden resets.",
    format: (v) => `${v} trees`,
  },
  {
    key: "worldSize",
    label: "World size",
    group: "garden",
    min: 8,
    max: 26,
    step: 1,
    resetOnly: true,
    help: "Radius of the garden dish.",
    format: fixed(0, " m"),
  },

  {
    key: "blueEnergyUse",
    label: "Energy use",
    group: "blue",
    min: 0.4,
    max: 6,
    step: 0.1,
    help: "Energy burned per second while moving at full speed. Waiting burns about a quarter of this.",
    format: fixed(1, "/s"),
  },
  {
    key: "blueSpeed",
    label: "Speed",
    group: "blue",
    min: 0.5,
    max: 4.5,
    step: 0.1,
    help: "Top speed. Faster moves cost more energy (cost grows with speed squared).",
    format: fixed(1, " m/s"),
  },
  {
    key: "blueVision",
    label: "Vision",
    group: "blue",
    min: 1,
    max: 12,
    step: 0.5,
    help: "How far a blue blob can spot fruit and red blobs.",
    format: fixed(1, " m"),
  },
  {
    key: "blueCopy",
    label: "Copy threshold",
    group: "blue",
    min: 25,
    max: 160,
    step: 1,
