function calmEnoughToCopy(w: World, b: Blob) {
  const mode = RULES.fearBlocksCopy;
  if (mode === 0 || w.time - b.lastThreatAt >= RULES.hideMemory) return true;
  return mode === 1 ? !b.sheltered : false;
}

function thinkBlue(w: World, b: Blob) {
  const p = w.params;
  const vis = p.blueVision * b.genes.vision;
