    v.rz = z;
    v.rh = h;
    v.ry = y;
    v.rs = r * scale;

    this.e.set(pitch, Math.PI / 2 - h + yawWobble, v.roll, "YXZ");
    this.q.setFromEuler(this.e);
    const rs = r * scale;
    this.bm.compose(this.p.set(x, y, z), this.q, this.s.set(rs * sxz, rs * sy, rs * sxz));
    this.body.setMatrixAt(i, this.bm);

