        <div>
          <div className="insp-name">{b.name}</div>
          <div className="insp-sub">
            {b.species === "blue" ? "Blue" : "Red"} group · generation {b.generation}
          </div>
        </div>
      </div>

      <div className={`insp-action act-${b.action}`}>{describe(w, b)}</div>

      {t && (
        <div className="insp-timer">
          <span>{t.label}</span>
