          <em style={{ left: `${(thr / max) * 100}%` }} title="Copy threshold" />
        </span>
      </div>

      <dl className="insp-grid">
        <dt>Age</dt>
        <dd>{fmtTime(b.age)}</dd>
        <dt>Speed</dt>
        <dd>
          {b.speed.toFixed(1)} <small>/ {topSpeedOf(b, p).toFixed(1)} m/s</small>
        </dd>
        <dt>Sensing</dt>
        <dd>{visionOf(b, p).toFixed(1)} m</dd>
        <dt>{b.species === "blue" ? "Fruit eaten" : "Contacts"}</dt>
