      mode === "log" ? pad.t + ph - (Math.log10(1 + Math.max(0, v)) / logTop) * ph : pad.t + ph - (v / left.max) * ph;
    const YR = (v: number) => pad.t + ph - (v / right.max) * ph;
    const yOf = (k: Key) => (k === "red" && dual ? YR : YL);

