                {label}
              </button>
            ))}
          </div>
        </div>
      </header>
      <div className="chart-box tall">
        <canvas
          ref={ref}
          className="chart-canvas"
          onPointerMove={(e) => {
            hover.current = e.clientX - e.currentTarget.getBoundingClientRect().left;
