    this.disposed = true;
    cancelAnimationFrame(this.raf);
    this.ro.disconnect();
    this.controls.dispose();
    this.blobs.dispose();
    this.trees?.dispose();
    this.particles.dispose();
    this.renderer.dispose();
    this.renderer.domElement.remove();
  }
}

