      new THREE.TorusGeometry(1, 0.06, 10, 64).rotateX(Math.PI / 2),
      new THREE.MeshBasicMaterial({ color: "#fff3a8", transparent: true, opacity: 0.95, depthWrite: false }),
    );
    this.visionRing = new THREE.Mesh(
