      this.camera.position.set(Math.sin(polar) * Math.sin(az) * dist, Math.cos(polar) * dist, Math.sin(polar) * Math.cos(az) * dist);
    }
    this.controls.minDistance = radius * 0.5;
    this.controls.maxDistance = dist * 1.8;
    this.camera.lookAt(0, 0, 0);
