    return (l.trunkH + 1.5) * this.trees[id].scale;
  }

  update(world: World, time: number, dt: number, mouthOf: MouthLookup) {
    const limit = Math.min(SLOTS, Math.round(world.params.fruitLimit));
    const { m, tm, lm, q, e, v, v2, s, c } = this;

