      }
    }
    return best;
  }

  dispose() {
    for (const mesh of [this.trunks, this.canopy, this.fruits, this.leaves]) {
      mesh.geometry.dispose();
      (mesh.material as THREE.Material).dispose();
      mesh.dispose();
    }
  }
