import { useEffect } from "react";
import { ControlsPanel } from "./ui/ControlsPanel";
import { GardenView } from "./ui/GardenView";
import { Header } from "./ui/Header";
import { PhasePlot } from "./ui/charts/PhasePlot";
import { TimelineChart } from "./ui/charts/TimelineChart";
import { TraitChart } from "./ui/charts/TraitChart";
import { SummaryPanel } from "./ui/SummaryPanel";
import { ctrl } from "./ui/sim";

function useShortcuts() {
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      const el = e.target as HTMLElement | null;
      const typing = el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA" || el.isContentEditable);
      const isRange = el instanceof HTMLInputElement && el.type === "range";
      if (typing && !(isRange && (e.key === " " || e.key === "Escape"))) return;
      switch (e.key) {
        case " ":
          if (el?.tagName === "BUTTON") return;
          e.preventDefault();
          ctrl.toggle();
          break;
        case ".":
        case "ArrowRight":
          if (!ctrl.running) {
            e.preventDefault();
            ctrl.stepOnceManual();
          }
          break;
        case "r":
        case "R":
          ctrl.reset();
          break;
        case "f":
        case "F":
          if (ctrl.selected !== null) ctrl.setFollow(!ctrl.follow);
          break;
        case "Escape":
          ctrl.select(null);
          ctrl.selectTree(null);
          break;
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);
}

export function App() {
  useShortcuts();
  return (
    <div className="app">
      <Header />
      <main className="layout">
        <div className="stage">
          <GardenView />
          <TimelineChart />
          <div className="card-row">
            <SummaryPanel />
            <PhasePlot />
            <TraitChart />
          </div>
        </div>
        <ControlsPanel />
      </main>
    </div>
  );
}

