          break;
        }
        case "contact": {
          this.particles.burst(3, { shape: SHAPE.heart, x: ev.x, y: 0.95, z: ev.y, size: 0.42, life: 1.25, color: COLORS.heart, gravity: 0.4, sway: 1.5 }, 0.5, 1.1);
