          hasTarget = true;
        }
      }
      this.intent.visible = hasTarget;
      if (hasTarget) {
        this.intentPos.set([this.tmp.x, 0.06, this.tmp.z, this.tmp2.x, this.tmp2.y, this.tmp2.z]);
