          <span>Energy</span>
          <b>
            {Math.max(0, b.energy).toFixed(0)} <small>/ {thr} to copy</small>
          </b>
        </div>
        <span className={`bar energy ${b.species}`}>
          <i style={{ width: `${Math.max(0, Math.min(1, b.energy / max)) * 100}%` }} />
