        <button className={`btn small ${follow ? "is-on" : ""}`} onClick={() => ctrl.setFollow(!follow)} disabled={b.action === "fade"}>
          <FollowIcon width={15} height={15} />
          {follow ? "Following" : "Follow"}
        </button>
      </div>
    </>
  );
