        </div>
      </div>
      <div className="fruit-slots" aria-label="Fruit on this tree">
        {Array.from({ length: limit }, (_, s) => {
          const slot = t.slots[s];
          const cls = slot.claimedBy >= 0 ? "eaten" : slot.growth >= 1 ? "ripe" : slot.cooldown > 0 ? "empty" : "growing";
