          {b.parentId >= 0 && <small> · line of {founder ? founder.name : `#${b.founderId}`}</small>}
        </dd>
      </dl>

      <div className="insp-genes">
        <GeneBar label="Speed gene" value={b.genes.speed} />
        <GeneBar label="Vision gene" value={b.genes.vision} />
      </div>

